Definition am_pot (cs : mstate) : Z :=
  c_avail_meta_count (s_ctx cs) + NSLOTS * c_avail_meta_area_count (s_ctx cs).
Definition pot (cs : mstate) : Z := NSLOTS * 2 ^ (c_meta_alloc_shift (s_ctx cs)) - am_pot cs.
Definition POT0 : Z := NSLOTS.        (* [comment removed for export] *)

Lemma pot_init : forall secret resv, pot (strip (minit secret resv)) = POT0.
Proof.
ltac2:(KReplay.run1 (kr_t_BrRes ()) ["CEIL_WRAP_1"] "h04resvh16secretp;2p;1g0000j22Tg000Pj11Tg0010j20Tg001JR01200#1g001h,00W0W1o"). Qed.

